  replacement='\nvfx_gate:\n  id: '+gate['id']+'\n  status: PENDING_OWNER_APPROVAL\n  frame: F03\n  version: '+job['version']+'\n  generated: 1\n  remaining_native_vfx_frames: 101\n  official_manifest_assets: 202\n  runtime_admission: false\n  receipt: .atena/generated/s007-reconciliation/v01/f03-owner-gate-2026-10-09.json\n'
  t=t[:match.start()]+replacement+t[match.end():]
